SINA_SMART["physio1-anorectal"] = {"lecture":"physio1-anorectal","title":"Anorectal motility","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-anorectal:e0","text":"IAS: smooth, involuntary, ~70% of resting tone.","topic":"Anatomy","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e1","text":"EAS: striated, voluntary (pudendal nerve).","topic":"Anatomy","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e3","text":"Rest: rectum ~3 cmH₂O; anal canal 50-100 cmH₂O.","topic":"Storage and continence","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e4","text":"Continence: compliance, sphincters, initial continence, rectal adaptation.","topic":"Storage and continence","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e5","text":"RAIR: IAS relaxes (sampling). RAER: EAS contracts (guarding).","topic":"Pre-defecation reflexes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e2","text":"Puborectalis keeps the anorectal angle ~80-90°.","topic":"Expulsion","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e6","text":"Defecation: EAS and puborectalis relax, angle widens, Valsalva.","topic":"Expulsion","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e7","text":"Tests: anorectal manometry, endoanal ultrasound, defecography.","topic":"Tests and disorders","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-anorectal:e8","text":"Dyssynergia/anismus: paradoxical pelvic floor contraction.","topic":"Tests and disorders","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"3gtmhq":"a","1ytipls":"a","xmrf4s":"a","1w75gbi":"a","e2l73x":"a","15d8yks":"a","1oxzyej":"a","1t22i9a":"a","7iyxdj":"a","14o0h28":"a","18pv8g9":"a","1r8pwo2":"a","snt0o3":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-anorectal:e0":{"s":0,"u":["IAS: smooth, involuntary, ~70% of resting tone.","The anal sphincter complex has three parts: the internal anal sphincter (IAS) , a thickening of the circular smooth muscle, involuntary , providing about 70% of resting anal tone ; the external anal sphincter (EAS) , striated and voluntary (pudendal nerve); and the puborectalis , part of the levator ani, a sling around the anorectal junction that keeps the anorectal angle at about 80-90° ."],"dp":[]},"physio1-anorectal:e1":{"s":0,"u":["EAS: striated, voluntary (pudendal nerve).","The anal sphincter complex has three parts: the internal anal sphincter (IAS) , a thickening of the circular smooth muscle, involuntary , providing about 70% of resting anal tone ; the external anal sphincter (EAS) , striated and voluntary (pudendal nerve); and the puborectalis , part of the levator ani, a sling around the anorectal junction that keeps the anorectal angle at about 80-90° ."],"dp":[]},"physio1-anorectal:e3":{"s":1,"u":["Rest: rectum ~3 cmH₂O; anal canal 50-100 cmH₂O.","At rest, rectal pressure is low (about 3 cmH₂O ) while the IAS keeps anal pressure at about 50-100 cmH₂O ; the EAS adds little at rest."],"dp":[]},"physio1-anorectal:e4":{"s":1,"u":["Continence: compliance, sphincters, initial continence, rectal adaptation.","Continence relies on: a capacitive system (rectal compliance : volume accepted with little pressure rise); a resistive system (IAS tone, voluntary EAS and levator ani); initial continence (quick EAS and pelvic floor contraction on sudden filling, short-lived because striated muscle fatigues); and rectal adaptation (the wall stretches and pressure falls, relieving the voluntary muscles)."],"dp":[]},"physio1-anorectal:e5":{"s":2,"u":["RAIR: IAS relaxes (sampling). RAER: EAS contracts (guarding).","Recto-anal excitatory reflex (RAER) : reflex contraction of the EAS , the guarding reflex that preserves continence while the IAS is relaxed.","Recto-anal inhibitory reflex (RAIR) : transient relaxation of the IAS while the EAS stays contracted, allowing the anal canal to sample contents."],"dp":[]},"physio1-anorectal:e2":{"s":3,"u":["Puborectalis keeps the anorectal angle ~80-90°.","Parasympathetic pelvic nerves inhibit IAS tone; the EAS and puborectalis relax voluntarily via the pudendal nerve (S2-S4) , so the anorectal angle straightens.","One slide says the anorectal angle goes 'from ~90° to ~15-20°' while also saying it increases."],"dp":[{"h":"Why squatting helps","t":"Sitting upright keeps the puborectalis partly contracted and the anorectal angle relatively sharp. Squatting flexes the hips, stretches the puborectalis and straightens the anorectal angle, so less straining is needed. That is the physiological basis of footstools used for constipation and of biofeedback therapy for dyssynergic defecation."}]},"physio1-anorectal:e6":{"s":3,"u":["Defecation: EAS and puborectalis relax, angle widens, Valsalva.","Parasympathetic pelvic nerves inhibit IAS tone; the EAS and puborectalis relax voluntarily via the pudendal nerve (S2-S4) , so the anorectal angle straightens.","During defecation the angle becomes wider (more obtuse, around 130-140°) , which straightens the passage."],"dp":[]},"physio1-anorectal:e7":{"s":4,"u":["Tests: anorectal manometry, endoanal ultrasound, defecography.","Tests: rectosigmoidoscopy or colonoscopy, high-resolution anorectal manometry (pressures, reflexes, coordination), endoanal ultrasound (sphincter defects), defecography (conventional or MRI)."],"dp":[]},"physio1-anorectal:e8":{"s":4,"u":["Dyssynergia/anismus: paradoxical pelvic floor contraction.","Dyssynergic defecation : paradoxical contraction or failure of pelvic floor relaxation on straining: constipation, excessive straining, incomplete evacuation.","Anismus : failure of puborectalis and/or EAS relaxation, with obstructed defecation."],"dp":[]}},"meta":{"3gtmhq":{"a":"recall","vg":"physio1-anorectal:e0/recall/1"},"1ytipls":{"a":"recall","vg":"physio1-anorectal:e1/recall/1"},"xmrf4s":{"a":"recall","vg":"physio1-anorectal:e2/recall/1"},"1w75gbi":{"a":"recall","vg":"physio1-anorectal:e5/recall/1"},"e2l73x":{"a":"recall","vg":"physio1-anorectal:e5/recall/1"},"15d8yks":{"a":"recall","vg":"physio1-anorectal:e4/recall/1"},"1oxzyej":{"a":"recall","vg":"physio1-anorectal:e1/recall/2"},"1t22i9a":{"a":"recall","vg":"physio1-anorectal:e6/recall/1"},"7iyxdj":{"a":"recall","vg":"physio1-anorectal:e3/recall/1"},"14o0h28":{"a":"recall","vg":"physio1-anorectal:e8/recall/1"},"18pv8g9":{"a":"recall","vg":"physio1-anorectal:e7/recall/1"},"1r8pwo2":{"a":"recall","vg":"physio1-anorectal:e4/recall/2"},"snt0o3":{"a":"recall","vg":"physio1-anorectal:e5/recall/2"}},"explRev":"1e65bf3f1cfe"};
